import {World} from './world.js';
import {Simulator} from './sim.js';
import {SCENES,PRESETS,makePlan,ACTION_NAMES,validatePlan} from './data.js';
import {blocked} from './planner.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={cube:'m12 3 9 5v9l-9 5-9-5V8Zm0 0v10m9-5-9 5-9-5m9 5v9',layout:'M3 4h18v16H3Zm6 0v16m0-11h12',workflow:'M4 3h6v6H4Zm10 12h6v6h-6ZM7 9v8h7M14 6h6m-3-3v6',chart:'M4 3v18h17M8 16v-5m5 5V7m5 9V4',help:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4m0 4v.1M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',sliders:'M4 7h16M4 17h16M8 4v6m8 4v6',shuffle:'m3 4 6 0 6 16h6m-4-4 4 4-4 3M3 20h6L15 4h6m-4-3 4 3-4 4',download:'M12 3v12m-4-4 4 4 4-4M4 15v6h16v-6',upload:'M12 16V3m-4 4 4-4 4 4M4 15v6h16v-6',camera:'M3 7h4l2-3h6l2 3h4v14H3ZM12 10a4 4 0 1 0 0 8 4 4 0 0 0 0-8',expand:'M9 3H3v6m12-6h6v6M3 15v6h6m12-6v6h-6',orbit:'M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6M5 5c-6 6 8 20 14 14S11-1 5 5Z',robot:'M7 7h10v7H7Zm5-4v4m-8 4h3m10 0h3M8 17h8v5M8 22v-5m2-6v.1m4-.1v.1',eye:'M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12Zm10-3a3 3 0 1 0 0 6 3 3 0 0 0 0-6',top:'m12 3 9 5-9 5-9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5',focus:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',home:'m3 11 9-8 9 8M5 10v11h14V10m-10 11v-7h6v7',play:'m7 4 14 8-14 8Z',pause:'M8 4v16M16 4v16',step:'m5 4 12 8-12 8ZM20 4v16',reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',history:'M3 11a9 9 0 1 1 2 7M3 5v6h6m3-4v6l4 2',arrowUpRight:'M6 18 18 6M6 6h12v12',arrowUp:'m6 10 6-6 6 6m-6-6v16',terminal:'m4 6 6 6-6 6m9 0h7',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0ZM5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8',gamepad:'M7 7h10c4 0 7 12 3 13l-5-4H9l-5 4C0 19 3 7 7 7Zm0 3v5m-2-2h4m7-2v.1m3 2v.1',pin:'M12 22s8-8 8-13a8 8 0 1 0-16 0c0 5 8 13 8 13Zm0-17a3 3 0 1 0 0 6 3 3 0 0 0 0-6',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Zm-5 10 3 3 7-7',stop:'M5 5h14v14H5Z',plus:'M12 4v16M4 12h16',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7m4-7v7',close:'m5 5 14 14M5 19 19 5',check:'m4 12 5 5L20 6',coffee:'M4 5h13v9a6 6 0 0 1-12 0V5Zm13 2h3a3 3 0 0 1 0 6h-3M3 21h16',fork:'M4 3v6a3 3 0 0 0 6 0V3M7 3v19m12-19v19m0-19c-5 1-5 11 0 11',box:'m3 7 9-4 9 4v13H3Zm0 0h18m-9-4v7'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.cube}"/></svg>`;}
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
const previews={};
function art(scene){
 if(previews[scene])return `<img src="${previews[scene]}" alt="${SCENES[scene].name}三维场景预览">`;
 return `<div class="scene-preview-placeholder ${scene}"><span>${scene==='warehouse'?'LOGISTICS':scene==='cafe'?'COFFEE LAB':'DINING ROOM'}</span><small>3D ENVIRONMENT</small></div>`;
}

let world,sim,activePanel='task',clickMode=null,toaster,editorPlan,lastAutoScrolled=-1;
const STATE={ready:'待执行',running:'训练中',paused:'已暂停',complete:'已完成',manual:'遥操作',replay:'回放中',error:'执行中断',emergency:'急停中'};
function toast(t,error=false){clearTimeout(toaster);$('#toast').textContent=t;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;toaster=setTimeout(()=>$('#toast').hidden=true,4500);}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function setCamera(mode){world.setCamera(mode);$$('[data-camera]').forEach(b=>{b.classList.toggle('active',b.dataset.camera===mode);b.setAttribute('aria-pressed',String(b.dataset.camera===mode));});}
function panel(name){activePanel=name;$$('[data-panel]').forEach(b=>{b.classList.toggle('active',b.dataset.panel===name);b.setAttribute('aria-pressed',String(b.dataset.panel===name));});$$('.inspector-panel').forEach(p=>p.hidden=p.id!=='panel-'+name);document.dispatchEvent(new window.CustomEvent('studio:panel'));}
function renderScenes(){$('#sceneCards').innerHTML=Object.entries(SCENES).map(([id,s],i)=>`<button class="scene-card ${sim.scene===id?'active':''}" data-scene="${id}" aria-pressed="${sim.scene===id}"><span class="scene-card-index">0${i+1}<span>${sim.scene===id?'ACTIVE':'ENVIRONMENT'}</span>${icon(sim.scene===id?'arrowUpRight':'plus')}</span><div class="scene-art">${art(id)}</div><span class="scene-card-title"><b>${s.name}</b><span>${s.english}</span></span><small>${s.tag}</small></button>`).join('');}
function renderPlan(){const exam=sim.mode==='exam';$('#taskSteps').innerHTML=sim.plan.map((p,i)=>`<li data-step="${i}"><span class="step-dot">${String(i+1).padStart(2,'0')}</span><span>${exam?'考核动作 '+(i+1):esc(p.label)}</span><small>${exam?'':ACTION_NAMES[p.type]}</small></li>`).join('');$('#stepTrack').innerHTML=sim.plan.map((p,i)=>`<span data-track="${i}" title="${esc(p.label)}"></span>`).join('');$('#totalSteps').textContent=sim.plan.length;lastAutoScrolled=-1;}
function sceneUI(){renderScenes();$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===sim.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===sim.mode));});$('#sceneTitle').textContent=SCENES[sim.scene].title;const index=Object.keys(SCENES).indexOf(sim.scene)+1;$('#app').dataset.environment=sim.scene;$('#headingSubtitle').textContent=SCENES[sim.scene].subtitle;$('#sceneNumber').textContent='/ 0'+index;$('#sceneEnglish').textContent=SCENES[sim.scene].english+' / 0'+index;$('#sceneSubtitle').textContent=SCENES[sim.scene].subtitle;$('#taskSelect').innerHTML=PRESETS[sim.scene].map(p=>`<option value="${p[0]}">${p[1]}</option>`).join('');$('#taskSelect').value=sim.preset;$('#taskDesc').textContent=PRESETS[sim.scene].find(p=>p[0]===sim.preset)?.[2]||'自定义动作序列';$('#tableField').hidden=sim.scene==='warehouse'||(sim.scene==='restaurant'&&sim.preset==='service');$('#tableSelect').value=sim.table;$('#commandInput').placeholder=sim.scene==='warehouse'?'试试：搬运易碎品':sim.scene==='cafe'?'试试：做一杯拿铁送到2号桌':'试试：给3号桌上菜';const examples={warehouse:['搬运易碎品','入库上架'],cafe:['制作拿铁','来杯美式'],restaurant:['给2号桌上菜','回收1号桌餐盘']};$('#commandChips').innerHTML=examples[sim.scene].map(t=>`<button data-command="${t}">${t}</button>`).join('');$('#seedLabel').textContent=(sim.seed===1?'标准':'随机')+'场景 · SEED '+String(sim.seed).padStart(3,'0');renderPlan();setCamera('orbit');updateObject(null);clearClickMode();sync();document.dispatchEvent(new window.CustomEvent('studio:scenechange',{detail:{scene:sim.scene,subtitle:SCENES[sim.scene].subtitle}}));}
function updateObject(id){world.select(id);$('#selectionTip').hidden=!id;$('#objectHint').hidden=!!id;$('#objectDetail').hidden=!id;if(!id)return;const o=world.entities[id];$('#selectedName').textContent=o.name;$('#objectDetail').innerHTML=`<h3>${esc(o.name)}</h3><div class="object-grid"><div><span>物体编号</span><b>${esc(id.toUpperCase())}</b></div><div><span>状态</span><b>${esc(o.status)}</b></div><div><span>尺寸 / m</span><b>${o.w.toFixed(2)} × ${o.h.toFixed(2)} × ${o.d.toFixed(2)}</b></div><div><span>设定质量</span><b>${o.weight} kg</b></div><div><span>操作属性</span><b>${o.fragile?'易碎 / 低速搬运':o.kind==='cargo'?'双臂搬运':'托举与配送'}</b></div></div>${sim.scene==='warehouse'?'<button class="wide-button" data-action="moveSelected">编排此物体搬运</button>':''}<button class="wide-button quiet" data-action="focusSelected">聚焦物体</button>`;}
function renderLogs(){if(!sim)return;$('#eventLog').innerHTML=sim.logs.slice(-3).map(l=>`<div class="event-item ${l.kind}"><time>${l.time.toFixed(1)}s</time><span>${esc(l.text)}</span></div>`).join('');}
function sync(){if(!sim)return;const replay=sim.state==='replay';const f=replay?sim.frames[sim.replayIndex]:null;const elapsed=f?.time??sim.elapsed;const step=f?.step??sim.completed;const m=Math.floor(elapsed/60),s=(elapsed%60).toFixed(1).padStart(4,'0');$('#elapsed').textContent=String(m).padStart(2,'0')+':'+s;$('#distance').innerHTML=(f?.distance??sim.distance).toFixed(2)+' <small>m</small>';$('#completion').innerHTML=Math.round(step/sim.plan.length*100)+' <small>%</small>';$('#collisions').innerHTML=sim.collisions+' <small>次</small>';$('#stepCount').textContent=step;$('#taskBadge').textContent=STATE[sim.state];$('#taskBadge').className='pill '+sim.state;$('#viewStatus').textContent=sim.state==='ready'?'场景就绪':STATE[sim.state];$('#statusText').textContent=sim.state==='complete'?'训练完成 · '+sim.result.score+' 分':STATE[sim.state];if($('#app').dataset.state!==sim.state){$('#app').dataset.state=sim.state;$('#playButton').innerHTML=icon(sim.state==='running'?'pause':'play')+'<span>'+(sim.state==='running'?'暂停训练':sim.state==='paused'?'继续训练':sim.state==='complete'?'再次训练':'开始训练')+'</span><kbd>SPACE</kbd>';}$('#stepLabel').textContent=sim.failure||(!replay&&sim.mode!=='exam'?sim.manipulation?.label:null)||((sim.state==='running'||sim.state==='paused'||replay)?(sim.mode==='exam'?'考核动作 '+(step+1):sim.plan[Math.min(step,sim.plan.length-1)]?.label):sim.state==='complete'?'全部任务完成 · '+sim.result.score+' 分':'等待开始');$('#replayControls').hidden=!replay;$('#stepTrack').hidden=replay;$('#replaySlider').max=Math.max(0,sim.frames.length-1);if(replay){$('#replaySlider').value=sim.replayIndex;$('#replayTime').textContent=elapsed.toFixed(1)+' / '+sim.frames.at(-1).time.toFixed(1)+' s';$('#replayPlay').textContent=sim.replayPlaying?'暂停回放':'播放回放';}$('#replayButton').classList.toggle('active',replay);$('#recordCount').textContent=sim.records.length;$('#manualButton').innerHTML=icon('gamepad')+(sim.state==='manual'?'关闭遥操作':'开启遥操作');$('#estopButton').innerHTML=icon('stop')+(sim.state==='emergency'?'解除急停':'机器人急停');$('#obstacleCount').textContent=sim.world.obstacles.filter(o=>o.custom).length+' 个';$('#posX').textContent=world.robot.position.x.toFixed(2)+' m';$('#posZ').textContent=world.robot.position.z.toFixed(2)+' m';$('#yaw').textContent=((world.robot.rotation.y*180/Math.PI%360+360)%360).toFixed(0)+'°';$('#held').textContent=world.held?(world.entities[world.held]?.name||world.held):'空闲';$('#storageStatus').textContent=sim.historyStorageAvailable?'记录保存在当前浏览器':'记录暂存内存 · 请及时导出';
 $$('#taskSteps li').forEach((el,i)=>{el.classList.toggle('done',i<step);el.classList.toggle('current',i===step&&['running','paused','replay'].includes(sim.state));el.firstElementChild.textContent=i<step?'✓':String(i+1).padStart(2,'0');});$$('#stepTrack span').forEach((el,i)=>{el.classList.toggle('done',i<step);el.classList.toggle('current',i===step&&sim.state==='running');});if(sim.state==='running'&&step!==lastAutoScrolled){lastAutoScrolled=step;const el=$(`#taskSteps li[data-step="${step}"]`);if(el){const parent=$('#taskSteps');parent.scrollTo({top:el.offsetTop-parent.firstElementChild.offsetTop-40,behavior:'smooth'});}}
 renderLogs();}
function setScene(id,preset=null,table=2,seed=1){if(!SCENES[id])return;sim.setup(id,preset||PRESETS[id][0][0],table,seed);sceneUI();}
function clearClickMode(){clickMode=null;$('#modeTip').hidden=true;world.canvas.style.cursor='grab';}
function setClickMode(mode){if(sim.state==='emergency'){toast('请先解除急停。');return;}if(['running','paused','replay'].includes(sim.state)){toast('请先重置训练，再编辑环境或自由导航。');return;}clickMode=mode;$('#modeTip').hidden=false;$('#modeTip').textContent=mode==='obstacle'?'点击空地添加障碍 · Esc 取消':'点击空地导航 · Esc 取消';world.canvas.style.cursor='crosshair';}
function modal(title,html,eyebrow='FIELD / STUDIO'){$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=html;icons($('#modal'));if(!$('#modal').open)$('#modal').showModal();}
function showEditor(){if(['running','replay'].includes(sim.state)){toast('请暂停训练后再查看任务编排。');return;}editorPlan=structuredClone(sim.plan);modal('任务编排','<p class="modal-intro">调整动作顺序、导航坐标和动作时长。保存时会检查抓取与放置是否成对，并重置当前训练。</p><div id="editorRows"></div><div class="modal-actions"><button data-action="addWait">＋ 等待动作</button><button data-action="exportPlan">导出动作 JSON</button><button class="primary" data-action="savePlan">保存并应用</button></div>','TASK / COMPOSER');renderEditor();}
function renderEditor(){$('#editorRows').innerHTML=editorPlan.map((p,i)=>`<div class="plan-row"><span class="plan-number">${i+1}</span><span class="action-type">${ACTION_NAMES[p.type]}</span><input data-edit="label" data-index="${i}" value="${esc(p.label)}" aria-label="第${i+1}步名称" maxlength="60"><div class="params">${p.type==='move'?`X <input type="number" step=".25" min="-6.5" max="6.5" data-edit="x" data-index="${i}" value="${p.x}" aria-label="第${i+1}步X坐标">Z <input type="number" step=".25" min="-4.4" max="4.4" data-edit="z" data-index="${i}" value="${p.z}" aria-label="第${i+1}步Z坐标">`:`<input type="number" min=".1" max="60" step=".1" data-edit="duration" data-index="${i}" value="${p.duration}" aria-label="第${i+1}步时长"> 秒 ${esc(p.id||p.kind||'')}`}</div><div class="row-actions"><button data-edit-action="up" data-index="${i}" aria-label="上移第${i+1}步">↑</button><button data-edit-action="down" data-index="${i}" aria-label="下移第${i+1}步">↓</button><button data-edit-action="remove" data-index="${i}" aria-label="删除第${i+1}步">×</button></div></div>`).join('');}
function showRecords(){modal('训练记录',`<p class="modal-intro">保留最近 6 次完成的训练。成绩根据动作完成率、碰撞拦截、路径阻塞和任务用时计算；可回放完整轨迹或导出 JSON。</p>${sim.records.length?sim.records.map((r,i)=>`<article class="record-card"><div><h3>${esc(SCENES[r.scene]?.name||r.scene)} · ${esc(PRESETS[r.scene]?.find(p=>p[0]===r.preset)?.[1]||'自定义任务')}</h3><small>${new Date(r.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})} · ${r.mode==='exam'?'考核':'练习'}</small><div class="record-stats"><span>${r.elapsed.toFixed(1)} s</span><span>${r.distance.toFixed(2)} m</span><span>${r.collisions} 次碰撞拦截</span><span>${r.result.passed?'达标':'待提升'}</span></div></div><div class="record-score">${r.result.score}<small> 分</small></div><div class="record-actions"><button data-record="${i}" data-record-action="replay">回放轨迹</button><button data-record="${i}" data-record-action="export">导出记录</button><button data-record="${i}" data-record-action="delete">删除</button></div></article>`).join(''):'<div class="empty-state">'+icon('chart')+'这里将记录每一次进步。<br>先完成一项训练，生成你的第一份报告。</div>'}`,'TRAINING / HISTORY');}
function showResult(){if(!sim.startTime&&!sim.completed){toast('开始训练后即可查看过程成绩。');return;}const r=sim.result;modal('训练成绩',`<div class="result-hero"><span class="result-number">${r.score}</span><div><h3>${r.passed?'本次训练达标':'训练仍在进行或尚未达标'}</h3><p>${esc(SCENES[sim.scene].name)} · ${sim.completed} / ${sim.plan.length} 个动作完成</p></div></div><table class="log-table"><tr><th>评分项目</th><th>本次记录</th><th>计算规则</th></tr><tr><td>完成基础分</td><td>${r.completion} 分</td><td>已完成动作 / 总动作 × 100</td></tr><tr><td>安全扣分</td><td>−${r.safety} 分</td><td>碰撞拦截 × 10 + 路径阻塞 × 3，上限 40</td></tr><tr><td>用时扣分</td><td>−${r.timePenalty} 分</td><td>超过 ${SCENES[sim.scene].time}s 后每 5s 扣 1 分，上限 20</td></tr><tr><td>行走距离</td><td>${sim.distance.toFixed(2)} m</td><td>累计机器人底座位移</td></tr><tr><td>达标条件</td><td>${r.passed?'已满足':'未满足'}</td><td>完成所有动作，且得分 ≥ 80</td></tr></table><div class="modal-actions"><button data-action="exportRun">导出完整记录</button><button class="primary" data-action="modalReplay">查看轨迹回放</button></div>`,'TRAINING / REPORT');}
function showHelp(){modal('从第一步，到完整任务',`<p class="modal-intro">为教学演示、任务设计和交互验证构建的浏览器三维训练原型。默认包含 3 个环境、10 个任务模板和 5 种相机视角。</p><div class="guide-grid"><div class="guide-card"><h3>01 / 选择场景与任务</h3><p>切换左侧仓库、咖啡店或餐馆，在右侧选择任务。咖啡制作和单桌服务可以指定桌位。点击「开始训练」运行整个任务。</p></div><div class="guide-card"><h3>02 / 观察与控制</h3><p>左键拖动旋转，右键平移，滚轮缩放。数字 1–5 切换相机；空格开始/暂停；R 重置。单步按钮会运行一个完整动作后暂停。</p></div><div class="guide-card"><h3>03 / 机器人遥操作</h3><p>在机器人面板开启遥操作，使用 WASD 或方向键移动，E 抓取/放置。咖啡杯采用走近、伸手接触杯柄、稳持抬杯的完整动作；放杯时落稳后再松手。也可选择「点击地面导航」规划路线。急停会立即停止运动。</p></div><div class="guide-card"><h3>04 / 场景与任务编排</h3><p>点击物体检查属性；仓库中可直接编排该货物搬运。环境面板可放置障碍，任务编排支持修改坐标、名称、时长和动作顺序，以及加入等待动作。</p></div><div class="guide-card"><h3>05 / 指令与回放</h3><p>输入「制作拿铁」「给2号桌上菜」「回收1号桌餐盘」等快捷指令，系统解析后运行相应任务。完成训练后拖动回放时间轴，查看机器人和物体的历史状态。</p></div><div class="guide-card"><h3>06 / 训练数据与评分</h3><p>练习模式展示动作提示，考核模式隐藏动作说明。两个模式采用相同公开评分规则。记录保留在当前浏览器，支持 JSON 导出，场景配置支持导入复用。</p></div></div><div class="guide-note"><b>当前实现范围</b><br>机器人使用 Unitree 官方 G1 的 CAD 网格和 URDF 关节结构，动作采用运动学演示；导航使用网格 A*；抓取与咖啡加工是运动学和视觉状态模拟。当前版本未连接真实机器人、ROS 2、物理动力学引擎或大模型，也不进行强化学习模型训练。机器人网格采用来源尺寸，物体质量和考核阈值为本原型设置值。语音输入使用浏览器识别能力，需浏览器支持并允许麦克风，文字指令可直接使用。</div><p class="asset-credit">模型来源：<a href="https://github.com/unitreerobotics/unitree_ros/tree/master/robots/g1_description" target="_blank" rel="noopener">Unitree Robotics / G1</a>（BSD-3-Clause）。场景模型：<a href="https://huggingface.co/datasets/nvidia/simready-assets" target="_blank" rel="noopener">NVIDIA SimReady</a>（CC BY 4.0，14 类模型，已转换与优化）。材质与环境光：<a href="https://polyhaven.com" target="_blank" rel="noopener">Poly Haven</a>（CC0）。<a href="./assets/ATTRIBUTION.txt" target="_blank">资源署名与许可</a>。本项目与上述资源提供方无官方合作关系。</p><div class="modal-actions"><a class="primary" href="./download.html" target="_blank" rel="noopener">下载离线源码包</a><button class="primary" data-action="closeModal">开始探索</button></div>`,'QUICK / GUIDE');}
function scenario(){return {format:'embodied-studio-scenario',version:1,scene:sim.scene,preset:sim.preset,table:sim.table,seed:sim.seed,mode:sim.mode,plan:sim.plan,obstacles:world.obstacles.filter(o=>o.custom).map(o=>({x:o.x,z:o.z})),display:{labels:world.labelsEnabled,sensor:world.sensorGroup.visible},render:{...world.pipeline.settings}};}
function syncRender(){const r=world.pipeline.settings;$('#qualitySelect').value=r.quality;$('#lightingSelect').value=r.lighting;$('#exposureRange').value=r.exposure;$('#exposureValue').textContent=r.exposure.toFixed(2);$('#aoCheck').checked=r.ao;$('#aoCheck').disabled=r.quality==='performance';}
function setToggle(name,value){if(!['labels','sensor'].includes(name))return;if(name==='labels'){world.labelsEnabled=value;world.labelGroup.visible=value;}if(name==='sensor'){world.sensorGroup.visible=value;world.updateSensors();}const b=$(`[data-toggle="${name}"]`);b?.classList.toggle('active',value);$('#'+name+'Check').checked=value;}
function command(text){if(!world.assetReady){toast('三维资源正在加载，请稍候。');return;}text=text.trim();if(!text)return;$('#commandInput').value=text;if(/暂停|停止|急停/.test(text)){if(/急停/.test(text))sim.stop();else if(sim.state==='running')sim.toggle();else toast('当前未在执行任务。');return;}if(/继续|开始/.test(text)){sim.start();return;}if(/全景|自由视角/.test(text)){setCamera('orbit');return;}if(/跟随/.test(text)){setCamera('follow');return;}if(/俯视|顶视/.test(text)){setCamera('top');return;}const t=Number(text.match(/([123])\s*号?桌/)?.[1]||2);let scene,preset;if(/咖啡|拿铁|美式|卡布|浓缩/.test(text)){scene='cafe';preset=/美式/.test(text)?'americano':/卡布/.test(text)?'cappuccino':/浓缩/.test(text)?'espresso':'latte';}else if(/上菜|餐盘|回收/.test(text)){scene='restaurant';preset=/回收/.test(text)?'return':'single';}else if(/搬|货|上架|入库|分拣/.test(text)){scene='warehouse';preset=/易碎/.test(text)?'fragile':/上架|入库/.test(text)?'restock':'sort';}else{toast('支持咖啡制作、上菜、回收、货物分拣、暂停及视角指令。');return;}setScene(scene,preset,t);sim.log('已解析指令：'+text,'success');sim.start();toast('已编排并开始：'+text);}
const actions={
 renderSettings(){panel('environment');$('#qualitySelect').focus();},resetRender(){world.configureRender({quality:'balanced',lighting:'day',exposure:1.05,ao:true});syncRender();toast('已恢复默认渲染设置');},workspace(){if($('#modal').open)$('#modal').close();panel('task');},help:showHelp,editor:showEditor,records:showRecords,result:showResult,
 closeModal(){$('#modal').close();},play(){if(!world.assetReady){toast('三维资源正在加载，请稍候。');return;}clearClickMode();if(sim.state==='replay'){sim.replayPlaying=!sim.replayPlaying;}else sim.toggle();},step(){if(!world.assetReady)return;clearClickMode();sim.start(true);},reset(){sim.reset();renderPlan();clearClickMode();updateObject(null);toast('场景与任务已重置');},replay(){if(sim.state==='replay')sim.exitReplay();else sim.enterReplay();sync();},replayPlay(){sim.replayPlaying=!sim.replayPlaying;},exitReplay(){sim.exitReplay();},modalReplay(){$('#modal').close();sim.enterReplay();sceneUI();},homeCamera(){setCamera('orbit');},
 fullscreen(){if(document.fullscreenElement)document.exitFullscreen();else $('#viewport').requestFullscreen().catch(()=>toast('当前浏览器不支持全屏。'));},screenshot(){world.render(0);const a=document.createElement('a');a.href=world.canvas.toDataURL('image/png');a.download='具身工场-'+SCENES[sim.scene].name+'.png';a.click();toast('已保存当前三维视图');},manual(){clearClickMode();sim.manual();},interact(){sim.interact();},navigate(){setClickMode('navigate');},addObstacle(){setClickMode('obstacle');},clearObstacles(){if(sim.state==='running'){toast('请先暂停训练。');return;}world.clearObstacles();world.updateSensors();sim.log('已移除自定义障碍。');sync();},estop(){clearClickMode();if(sim.state==='emergency')sim.release();else sim.stop();},
 clearSelection(){updateObject(null);},focusSelected(){if(world.selected){const obj=world.entities[world.selected];setCamera('close');const point=obj.mesh.getWorldPosition(world.camera.position.clone());world.camGoal.target.copy(point).add({x:0,y:.3,z:0});world.camGoal.pos.copy(point).add({x:2.5,y:2,z:3});}},moveSelected(){const id=world.selected;if(!id)return;sim.reset();sim.plan=makePlan('warehouse','sort',2,id);renderPlan();panel('task');toast('已编排所选物体，点击开始训练即可执行。');},
 randomize(){const seed=Math.floor(Math.random()*999)+2;setScene(sim.scene,sim.preset,sim.table,seed);const candidates=[[-1,0],[2,.2],[1.5,3.3],[-5.7,-.5],[5.7,.6]];for(let i=0;i<2;i++){const p=candidates[(seed+i*2)%candidates.length];if(!blocked(...p,world.obstacles,.8))world.addObstacle(...p);}sim.log('已更新货物规格与障碍布局，SEED '+seed);sync();toast('已生成新的训练布置');},
 exportScenario(){download('具身工场-场景配置.json',JSON.stringify(scenario(),null,2));},importScenario(){$('#configFile').click();},exportRun(){download('具身工场-训练记录.json',JSON.stringify(sim.exportRecord()));},exportPlan(){download('具身工场-动作序列.json',JSON.stringify({scene:sim.scene,plan:editorPlan},null,2));},
 addWait(){editorPlan.push({type:'wait',label:'等待安全确认',duration:2,key:'wait-'+Date.now()});renderEditor();},savePlan(){const err=validatePlan(editorPlan,world.entities,world.targets);if(err){toast(err,true);return;}sim.reset();sim.plan=structuredClone(editorPlan);renderPlan();$('#modal').close();$('#taskDesc').textContent='已应用自定义动作序列';sim.log('已应用自定义任务，共 '+sim.plan.length+' 个动作。','success');toast('任务编排已应用');sync();},logs(){modal('运行日志','<table class="log-table"><thead><tr><th>仿真时间</th><th>事件</th></tr></thead><tbody>'+sim.logs.map(l=>`<tr><td>${l.time.toFixed(1)} s</td><td>${esc(l.text)}</td></tr>`).join('')+'</tbody></table><div class="modal-actions"><button data-action="exportRun">导出完整记录</button><button data-action="result">查看成绩</button></div>','RUN / EVENTS');},
 voice(){const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('当前浏览器不支持语音识别，请使用文字指令。');return;}const recognition=new Speech();recognition.lang='zh-CN';recognition.interimResults=false;recognition.onresult=e=>command(e.results[0][0].transcript);recognition.onerror=e=>toast(e.error==='not-allowed'?'麦克风未获授权，请使用文字输入。':'语音识别未完成，请重试或输入文字。');recognition.start();toast('正在聆听，请说出训练指令。');}
};
try{
 world=new World($('#sceneCanvas'));sim=new Simulator(world,()=>{if(sim)sync();},entry=>{if(sim){renderLogs();if(entry.kind==='error'||entry.kind==='warn')toast(entry.text,entry.kind==='error');if(entry.kind==='success'&&entry.text.includes('全部动作'))toast(entry.text+' 可在运行日志中查看成绩。');}});icons();sceneUI();
 if(world.headless)$('#loader').hidden=true;
 else{
  $('#app').inert=true;
  const assetProgress=setInterval(()=>{const count=world.assets.manifest?.assets.length;if(count)$('#assetProgress').textContent='场景模型 '+world.assets.completed+' / '+count+' · 正在准备机器人与环境光';},200);
  world.ready.then(()=>{
   clearInterval(assetProgress);
   const current={scene:sim.scene,preset:sim.preset,table:sim.table,seed:sim.seed};
   for(const id of Object.keys(SCENES)){world.load(id);world.setCamera('orbit',true);world.render(0);previews[id]=world.canvas.toDataURL('image/jpeg',.72);}
   sim.setup(current.scene,current.preset,current.table,current.seed);sceneUI();world.setCamera('orbit',true);
   $('#loader').hidden=true;$('#app').inert=false;
  }).catch(error=>{clearInterval(assetProgress);console.error(error);$('#app').inert=false;$('#loader').innerHTML='<b>资源加载未完成</b><span>'+esc(error.message)+'</span><span>请刷新页面重新加载。</span>';});
 }
 syncRender();
 $('#qualitySelect').addEventListener('change',e=>{world.configureRender({quality:e.target.value});syncRender();});
 $('#lightingSelect').addEventListener('change',e=>world.configureRender({lighting:e.target.value}));
 $('#exposureRange').addEventListener('input',e=>{world.configureRender({exposure:Number(e.target.value)});$('#exposureValue').textContent=Number(e.target.value).toFixed(2);});
 $('#aoCheck').addEventListener('change',e=>world.configureRender({ao:e.target.checked}));
 const resultBtn=document.createElement('button');resultBtn.className='square-button';resultBtn.dataset.action='result';resultBtn.title='本次成绩';resultBtn.setAttribute('aria-label','本次成绩');resultBtn.innerHTML=icon('chart');$('.run-buttons').insertBefore(resultBtn,$('.toolbar-divider'));
 document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;if(target.dataset.action){actions[target.dataset.action]?.();}if(target.dataset.scene)setScene(target.dataset.scene);if(target.dataset.panel)panel(target.dataset.panel);if(target.dataset.camera)setCamera(target.dataset.camera);if(target.dataset.mode){sim.mode=target.dataset.mode;$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===sim.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===sim.mode));});renderPlan();toast(sim.mode==='exam'?'已进入考核模式，动作提示已隐藏。':'已进入练习模式，动作提示已显示。');}if(target.dataset.toggle){const name=target.dataset.toggle;setToggle(name,!target.classList.contains('active'));}if(target.dataset.command)command(target.dataset.command);if(target.dataset.editAction){const i=Number(target.dataset.index),action=target.dataset.editAction;if(action==='remove')editorPlan.splice(i,1);else{const n=i+(action==='up'?-1:1);if(n>=0&&n<editorPlan.length)[editorPlan[i],editorPlan[n]]=[editorPlan[n],editorPlan[i]];}renderEditor();}if(target.dataset.recordAction){const i=Number(target.dataset.record);const r=sim.records[i];if(target.dataset.recordAction==='replay'){$('#modal').close();sim.enterReplay(r);sceneUI();}if(target.dataset.recordAction==='export')download('具身工场-'+r.id+'.json',JSON.stringify({format:'embodied-studio-run',version:1,...r}));if(target.dataset.recordAction==='delete'){sim.records.splice(i,1);sim.saveRecords();showRecords();sync();}}});
 document.addEventListener('input',e=>{if(e.target.dataset.edit){const {edit,index}=e.target.dataset;editorPlan[Number(index)][edit]=edit==='label'?e.target.value:Number(e.target.value);}});
 $('#taskSelect').addEventListener('change',e=>setScene(sim.scene,e.target.value,sim.table,sim.seed));$('#tableSelect').addEventListener('change',e=>setScene(sim.scene,sim.preset,Number(e.target.value),sim.seed));$('#speed').addEventListener('change',e=>sim.speed=Number(e.target.value));$('#replaySlider').addEventListener('input',e=>{sim.replayPlaying=false;sim.seek(Number(e.target.value));sync();});$('#commandForm').addEventListener('submit',e=>{e.preventDefault();command($('#commandInput').value);});['labels','sensor'].forEach(name=>$('#'+name+'Check').addEventListener('change',e=>setToggle(name,e.target.checked)));
 let pointerStart=null;world.canvas.addEventListener('pointerdown',e=>pointerStart={x:e.clientX,y:e.clientY});world.canvas.addEventListener('pointerup',e=>{if(!pointerStart||Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>5)return;const h=world.hit(e.clientX,e.clientY);if(!h)return;if(h.entity){updateObject(h.entity);panel('environment');}else if(h.robot){panel('robot');toast('已选择 Unitree G1，可在面板开启遥操作');}else if(h.floor&&clickMode){if(clickMode==='obstacle'){const {x,z}=h.point;if(blocked(x,z,world.obstacles,.8)||Math.hypot(x-world.robot.position.x,z-world.robot.position.z)<1.2){toast('请在远离机器人和现有物体的空地放置。');return;}world.addObstacle(x,z);world.updateSensors();sim.log('已添加障碍物。');toast('障碍物已添加，开始任务后可观察机器人绕行');sync();}else sim.goTo(h.point.x,h.point.z);clearClickMode();}else if(h.floor){updateObject(null);}});
 window.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('#modal').open||$('.stage-column').inert)return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)&&sim.state==='manual'){e.preventDefault();sim.keys.add(k);}if(e.repeat)return;if(k===' '){e.preventDefault();actions.play();}if(k==='r')actions.reset();if(k==='e')sim.interact();if(k==='escape')clearClickMode();if(['1','2','3','4','5'].includes(k))setCamera(['orbit','follow','first','top','close'][Number(k)-1]);});window.addEventListener('keyup',e=>sim.keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>sim.keys.clear());document.addEventListener('visibilitychange',()=>{if(document.hidden){sim.keys.clear();if(sim.state==='running')sim.toggle();}});$$('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(sim.state!=='manual'){toast('请先开启遥操作。');return;}b.setPointerCapture(e.pointerId);sim.keys.add(b.dataset.key);});b.addEventListener('pointerup',()=>sim.keys.delete(b.dataset.key));b.addEventListener('pointercancel',()=>sim.keys.delete(b.dataset.key));});
 $('#configFile').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw new Error('配置文件超过 2 MB');const c=JSON.parse(await file.text());if(c.format!=='embodied-studio-scenario'||c.version!==1||!SCENES[c.scene]||!PRESETS[c.scene].some(p=>p[0]===c.preset)||![1,2,3].includes(c.table)||!Number.isInteger(c.seed)||c.seed<1||c.seed>1e6||!Array.isArray(c.obstacles)||c.obstacles.length>30||!Array.isArray(c.plan)||c.plan.length>100)throw new Error('不是有效的场景配置');for(const o of c.obstacles)if(!Number.isFinite(o.x)||!Number.isFinite(o.z)||Math.abs(o.x)>6.2||Math.abs(o.z)>4.2)throw new Error('障碍坐标超出范围');for(const p of c.plan)if(typeof p.label!=='string'||p.label.length>80)throw new Error('动作名称无效');const old=scenario();setScene(c.scene,c.preset,c.table,c.seed);const err=validatePlan(c.plan,world.entities,world.targets);if(err){setScene(old.scene,old.preset,old.table,old.seed);old.obstacles.forEach(o=>world.addObstacle(o.x,o.z));sim.plan=old.plan;renderPlan();throw new Error(err);}sim.plan=c.plan;c.obstacles.forEach(o=>{if(!blocked(o.x,o.z,world.obstacles,.75)&&Math.hypot(o.x-world.robot.position.x,o.z-world.robot.position.z)>1.1)world.addObstacle(o.x,o.z);});sim.mode=c.mode==='exam'?'exam':'practice';$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===sim.mode);b.setAttribute('aria-pressed',String(b.dataset.mode===sim.mode));});for(const n of ['labels','sensor'])if(typeof c.display?.[n]==='boolean')setToggle(n,c.display[n]);if(c.render&&typeof c.render==='object'){world.configureRender(c.render);syncRender();}renderPlan();sync();toast('场景配置导入成功');}catch(err){toast('导入失败：'+err.message,true);}e.target.value='';});
 let last=performance.now(),uiTimer=0,sensorTimer=0,fpsTime=0,fpsFrames=0;function frame(t){const dt=Math.min((t-last)/1000,.06);last=t;sim.update(dt);world.render(dt);uiTimer+=dt;sensorTimer+=dt;fpsTime+=dt;fpsFrames++;if(uiTimer>.12){sync();uiTimer=0;}if(sensorTimer>.25&&world.sensorGroup.visible){world.updateSensors();sensorTimer=0;}if(fpsTime>=1){$('#fpsLabel').textContent=Math.round(fpsFrames/fpsTime)+' FPS';fpsFrames=0;fpsTime=0;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
 // Read-only diagnostic state for local verification and reproducible technical review.
 window.fieldStudio={get state(){return {scene:sim.scene,preset:sim.preset,status:sim.state,completed:sim.completed,total:sim.plan.length,elapsed:sim.elapsed,distance:sim.distance,result:sim.result,frames:sim.frames.length,records:sim.records.length,held:world.held,entities:Object.fromEntries(Object.entries(world.entities).map(([k,v])=>[k,{status:v.status,position:v.mesh.position.toArray()}])),failure:sim.failure,render:{...world.pipeline.settings},assets:{ready:world.assetReady,robot:world.rig.ready,textures:world.surfaces.loaded,simready:world.assets.loaded,simreadyModels:world.assets.models.size},manipulation:sim.manipulation?{kind:sim.manipulation.kind,phase:sim.manipulation.label,contact:sim.manipulation.contactEvent}:null,drawCalls:world.renderer.info?.render.calls};}};
}catch(error){console.error(error);$('#loader').innerHTML='<b>三维环境未能初始化</b><span>请使用支持 WebGL 2 的桌面浏览器，并开启硬件加速。</span><span>'+esc(error.message)+'</span>';}
